CREATE TABLE implementation_records (id UUID PRIMARY KEY, attempt_id UUID NOT NULL UNIQUE, stage_assessment_id UUID NOT NULL, language VARCHAR(80), implementation_status VARCHAR(40) NOT NULL, first_pass_compiled BOOLEAN NOT NULL DEFAULT FALSE, first_pass_passed_basic_cases BOOLEAN NOT NULL DEFAULT FALSE, first_pass_passed_edge_cases BOOLEAN NOT NULL DEFAULT FALSE, final_implementation_completed BOOLEAN NOT NULL DEFAULT FALSE, self_detected_error BOOLEAN NOT NULL DEFAULT FALSE, used_hint BOOLEAN NOT NULL DEFAULT FALSE, used_external_solution BOOLEAN NOT NULL DEFAULT FALSE, compile_error_count INTEGER NOT NULL DEFAULT 0, wrong_answer_count INTEGER NOT NULL DEFAULT 0, runtime_error_count INTEGER NOT NULL DEFAULT 0, timeout_count INTEGER NOT NULL DEFAULT 0, notes CLOB, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT fk_impl_attempt FOREIGN KEY(attempt_id) REFERENCES attempts(id), CONSTRAINT fk_impl_stage FOREIGN KEY(stage_assessment_id) REFERENCES stage_assessments(id));
CREATE TABLE implementation_errors (id UUID PRIMARY KEY, implementation_record_id UUID NOT NULL, error_type VARCHAR(64) NOT NULL, error_source VARCHAR(32) NOT NULL, severity VARCHAR(16) NOT NULL, description CLOB, failing_input CLOB, expected_output CLOB, actual_output CLOB, root_cause CLOB, correction CLOB, prevention_rule CLOB, recurrence_of_error_id UUID, created_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT fk_impl_error_record FOREIGN KEY(implementation_record_id) REFERENCES implementation_records(id));
CREATE INDEX idx_impl_errors_type ON implementation_errors(error_type);
